mapper.select:
SELECT s.id, s.user_id AS userId, s.agent_code AS agentCode, s.business_type AS businessType, s.business_id AS businessId, s.scene_code AS sceneCode, s.title, COUNT(m.id) AS messageCount, s.create_time AS createTime, s.update_time AS updateTime FROM ai_chat_session s LEFT JOIN ai_chat_message m ON m.session_id = s.id AND m.deleted = 0 WHERE s.user_id = #{userId} AND s.deleted = 0
AND s.agent_code = #{agentCode}
AND s.business_type = #{businessType}
AND s.business_id = #{businessId}
AND s.scene_code = #{sceneCode}
GROUP BY s.id, s.user_id, s.agent_code, s.business_type, s.business_id, s.scene_code, s.title, s.create_time, s.update_time ORDER BY s.update_time DESC
